  -- ---------------- SYLLABUS CHUNKS ----------------
  INSERT INTO syllabus_chunks (chunk_id, course_id, unit_number, sequence_order, topic_title, syllabus_content, slide_range, ltp_type, estimated_minutes, cognitive_complexity, co_mapping, bloom_level, canonical_keywords, is_deprecated) VALUES
  -- CS304 Foundations of Computer Vision
  ('50000000-0000-0000-0001-000000000101', c_cs304, 1, 1, 'Image Formation & the Pinhole Camera Model',
   'Light, scene radiance and the pinhole projection model. Perspective projection equations, focal length, image plane, homogeneous coordinates and the camera intrinsic matrix K.',
   'Slides 1-14', 'L', 40, 1.4, 'CO1', 'UNDERSTAND', '{pinhole,projection,focal length,intrinsic matrix,homogeneous coordinates}', false),
  ('50000000-0000-0000-0001-000000000102', c_cs304, 1, 2, 'Lens Optics: Aperture, f-Stop, Depth of Field & Circle of Confusion',
   'Thin lens equation, aperture diameter and f-number (f-stop), depth of field, circle of confusion and defocus blur. How aperture controls depth of field and how defocus blur is modelled as a point spread function for depth-from-defocus.',
   'Slides 15-30', 'L', 45, 1.6, 'CO1', 'APPLY', '{aperture,f-stop,depth of field,circle of confusion,thin lens,defocus blur}', false),
  ('50000000-0000-0000-0001-000000000103', c_cs304, 1, 3, 'Radiometry, Exposure, Sensor ISO Noise & Radiometric Calibration',
   'Irradiance, exposure as irradiance times shutter time, sensor gain (ISO), shot noise and read noise, the exposure triangle as a sensor model, camera response function, radiometric calibration and HDR merging.',
   'Slides 31-46', 'L', 45, 1.7, 'CO1', 'ANALYZE', '{exposure,iso,sensor noise,shutter speed,radiometric calibration,camera response,hdr}', false),
  ('50000000-0000-0000-0001-000000000104', c_cs304, 1, 4, 'Lab: Calibrating Exposure & Measuring Sensor Noise',
   'Capture dark frames and flat fields at multiple ISO values, estimate read noise and sensor gain, and fit the camera response curve.',
   'Lab Sheet 1', 'P', 60, 1.3, 'CO1', 'APPLY', '{iso,sensor noise,dark frame,camera response,exposure}', false),
  ('50000000-0000-0000-0001-000000000201', c_cs304, 2, 1, 'Image Filtering & Convolution',
   'Linear filters, convolution and correlation, Gaussian smoothing, separable kernels and the frequency-domain view with the Fourier transform.',
   'Slides 1-16', 'L', 40, 1.5, 'CO2', 'APPLY', '{convolution,gaussian,filter,kernel,fourier}', false),
  ('50000000-0000-0000-0001-000000000202', c_cs304, 2, 2, 'Edge Detection: Sobel & Canny',
   'Image gradients, gradient magnitude and orientation, the Sobel operator, non-maximum suppression and hysteresis thresholding in the Canny edge detector.',
   'Slides 17-30', 'L', 40, 1.4, 'CO2', 'APPLY', '{edge detection,gradient,sobel,canny,hysteresis}', false),
  ('50000000-0000-0000-0001-000000000203', c_cs304, 2, 3, 'Feature Detection: Harris Corners & SIFT',
   'Harris corner response from the structure tensor, scale space, difference of Gaussians, SIFT descriptors and feature matching with the ratio test.',
   'Slides 31-48', 'L', 45, 1.8, 'CO2', 'ANALYZE', '{harris,corner,structure tensor,sift,feature matching,scale space}', false),
  ('50000000-0000-0000-0001-000000000204', c_cs304, 2, 4, 'Lab: Edge & Feature Pipelines in OpenCV',
   'Implement Canny and Harris detectors and match SIFT features between two photographs.',
   'Lab Sheet 2', 'P', 60, 1.2, 'CO2', 'APPLY', '{canny,harris,sift,opencv}', false),
  ('50000000-0000-0000-0001-000000000301', c_cs304, 3, 1, 'Camera Calibration & Homography',
   'Intrinsic and extrinsic calibration with a checkerboard, lens distortion, the direct linear transform, homography estimation with RANSAC and panorama stitching.',
   'Slides 1-18', 'L', 45, 1.9, 'CO3', 'APPLY', '{calibration,checkerboard,intrinsic matrix,homography,ransac,distortion}', false),
  ('50000000-0000-0000-0001-000000000302', c_cs304, 3, 2, 'Stereo Vision & Epipolar Geometry',
   'The epipolar constraint, essential and fundamental matrices, rectification, disparity and depth from stereo.',
   'Slides 19-36', 'L', 45, 2.0, 'CO3', 'ANALYZE', '{stereo,epipolar,fundamental matrix,disparity,depth}', false),
  ('50000000-0000-0000-0001-000000000303', c_cs304, 3, 3, 'Optical Flow & Motion',
   'Brightness constancy, the Lucas-Kanade and Horn-Schunck methods, motion fields and feature tracking.',
   'Slides 37-50', 'L', 40, 1.8, 'CO3', 'ANALYZE', '{optical flow,lucas-kanade,motion,tracking}', false),
  ('50000000-0000-0000-0001-000000000304', c_cs304, 3, 4, 'Lab: Stereo Depth & Panorama Stitching',
   'Calibrate a stereo pair, compute a disparity map and stitch a panorama with RANSAC homographies.',
   'Lab Sheet 3', 'P', 60, 1.5, 'CO3', 'APPLY', '{stereo,disparity,homography,ransac}', false),
  ('50000000-0000-0000-0001-000000000401', c_cs304, 4, 1, 'CNNs for Image Classification',
   'Convolutional layers, pooling, ReLU, backpropagation, residual networks (ResNet) and transfer learning.',
   'Slides 1-20', 'L', 45, 1.7, 'CO4', 'APPLY', '{cnn,convolution,pooling,resnet,transfer learning}', false),
  ('50000000-0000-0000-0001-000000000402', c_cs304, 4, 2, 'Object Detection with YOLO',
