  -- ---------------- KNOWLEDGE GRAPH ----------------
  -- Intra-course chronological flow edges
  INSERT INTO knowledge_graph_edges (source_chunk_id, target_chunk_id, edge_type, similarity_score, shared_concepts, grounded_application_example)
