  -- Cross-subject bridges (closed-world: derived only from the two syllabus chunks)
  INSERT INTO knowledge_graph_edges (edge_id, source_chunk_id, target_chunk_id, edge_type, similarity_score, shared_concepts, grounded_application_example) VALUES
  ('a0000000-0000-0000-0000-000000000001', '50000000-0000-0000-0001-000000000102', '50000000-0000-0000-0002-000000000201', 'CROSS_SUBJECT_BRIDGE', 0.91,
   '{Aperture,f-Stop,Depth of Field,Circle of Confusion,Defocus Blur}',
   'In DES201 a wide aperture (low f-number) gives a shallow depth of field to isolate a portrait subject. In CS304 the same defocus blur, set by the circle of confusion in the thin-lens equation, is modelled as a point spread function and used as a depth cue (depth-from-defocus).'),
  ('a0000000-0000-0000-0000-000000000002', '50000000-0000-0000-0001-000000000103', '50000000-0000-0000-0002-000000000103', 'CROSS_SUBJECT_BRIDGE', 0.89,
   '{Exposure,ISO,Shutter Speed,Image Noise}',
   'The exposure triangle from DES201 (ISO, shutter speed, aperture) is the sensor model CS304 uses for radiometric calibration: exposure is irradiance times shutter time, and raising ISO raises sensor gain, amplifying the shot and read noise that CS304 measures from dark frames.');

