  ('70000000-0000-0000-0000-000000000003', c_cs204, '50000000-0000-0000-0003-000000000103', 2024, 'SEE', 'Explain the gamma characteristic of a CRT display and why gamma correction is applied to analog video.', 10, 'CO1', 'UNDERSTAND', '50000000-0000-0000-0001-000000000103', 0.41, 'FILTERED_OUT_DEPRECATED'),
